/*
 * A371653  Numbers k such that the number formed by putting the digits of k
 *          in descending order is prime.
 * https://oeis.org/A371653
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the nth integer k such that the number obtained by
 *            sorting the digits of k in descending order is prime. The
 *            sequence is generated by a simple brute‑force search
 * Range:     u8 n <= 24, u16 n <= 1687, u32 n <= 1687, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime_big.h"

/* Cache of found terms: a(1)=a[0] ... */
static seq_t *seq_cache = NULL;
static size_t seq_cap   = 0;
static size_t seq_len   = 0;
static idx_t next_candidate = 1;

/* Grow the cache to hold at least `needed` elements. */
static void ensure_cache(size_t needed)
{
    if (seq_cap < needed)
    {
        size_t new_cap = needed < 16 ? 16 : needed * 2;
        seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
        if (!tmp)
            exit(1);          /* allocation failure – unlikely under the limits */
        seq_cache = tmp;
        seq_cap   = new_cap;
    }
}

/* The required function: return the nth term of the sequence. */
seq_t a(idx_t n)
{
    if (n == 0)                /* offset is 1 – index 0 is outside the domain */
        return 0;

    while (seq_len < n)
    {
        idx_t k = next_candidate;                /* candidate number */

        /* collect the decimal digits of k */
        uint8_t digits[64];
        size_t dcnt = 0;
        if (k == 0)
            digits[dcnt++] = 0;
        else
        {
            idx_t t = k;
            while (t)
            {
                digits[dcnt++] = (uint8_t)(t % 10);
                t /= 10;
            }
        }

        /* sort digits in descending order (small dcnt → bubble sort) */
        for (size_t i = 0; i < dcnt; ++i)
            for (size_t j = i + 1; j < dcnt; ++j)
                if (digits[i] < digits[j])
                {
                    uint8_t u = digits[i];
                    digits[i] = digits[j];
                    digits[j] = u;
                }

        /* build the integer formed by those sorted digits */
        seq_t desc = 0;
        for (size_t i = 0; i < dcnt; ++i)
            desc = desc * 10 + digits[i];

        /* test primality of the descending integer */
        if (is_prime_big(desc))
        {
            ensure_cache(seq_len + 1);
            seq_cache[seq_len++] = (seq_t)k;
        }

        ++next_candidate;
    }

    return seq_cache[n - 1];
}
